    schema_anchor='const REUNION_SCHEMA:any={type:"OBJECT",properties:{bottom_line:S,contact_recontact:S,emotional_reactivation:S,relationship_rebuilding:S,incoming_contact:S,outgoing_contact:S,reconnection_windows:S,low_windows:S,relationship_filter:S,precision_note:S},required:["bottom_line","contact_recontact","emotional_reactivation","relationship_rebuilding","incoming_contact","outgoing_contact","reconnection_windows","low_windows","relationship_filter","precision_note"]};'
