    new_schema='if(purpose==="reunion")return {type:"OBJECT",properties:{headline:S,overview:S,timing:S,reunion_context:S,practical_advice:{type:"ARRAY",items:S},top_aspects:{type:"ARRAY",items:{type:"OBJECT",properties:{label:S,meaning:S},required:["label","meaning"]}},limits:S,reunion_synthesis_v2:REUNION_V2_SCHEMA},required:["headline","overview","timing","reunion_context","practical_advice","top_aspects","limits","reunion_synthesis_v2"]};'
    if old_schema in s: s=s.replace(old_schema,new_schema,1)
