def patch_public_error():
    p=Path('supabase/functions/relationship-interpret-v9-preview/publicError.ts'); s=load(p)
    marker='const MARRIAGE_LIMITS:Record<string,number>='
    if 'publicReunionV2' not in s:
        insert='''function textField(v:unknown,max:number){return typeof v==='string'&&v.length<=max*4?v:null;}\nfunction refList(v:unknown){return Array.isArray(v)&&v.length<=12&&v.every(x=>typeof x==='string'&&x.length<=180)?v.slice():null;}\nfunction publicReunionV2(value:unknown){const r=record(value);if(!r)return null;const sec=(v:unknown)=>{const x=record(v),refs=refList(x?.evidence_refs);if(!x||!refs)return null;const conclusion=textField(x.conclusion,2600),interpretation=textField(x.interpretation,3200);return conclusion!==null&&interpretation!==null?{conclusion,interpretation,evidence_refs:refs}:null;};const why=sec(r.why_reconnect),initiative=sec(r.initiative),t=record(r.timing),reb=record(r.rebuild),risk=record(r.repeat_risks);if(!why||!initiative||!t||!reb||!risk)return null;const timingRefs=refList(t.evidence_refs),rebuildRefs=refList(reb.evidence_refs),riskRefs=refList(risk.evidence_refs);if(!timingRefs||!rebuildRefs||!riskRefs)return null;const windows=Array.isArray(t.windows)&&t.windows.length<=4?t.windows.map((w:unknown)=>{const x=record(w),refs=refList(x?.evidence_refs);const period=textField(x?.period,120),meaning=textField(x?.meaning,1800);return x&&refs&&period!==null&&meaning!==null?{period,meaning,evidence_refs:refs}:null;}):[];if(windows.some(x=>x===null))return null;const convergence=Array.isArray(r.convergence)&&r.convergence.length<=5?r.convergence.map((c:unknown)=>{const x=record(c),refs=refList(x?.evidence_refs);const theme=textField(x?.theme,500),period=textField(x?.period,120),meaning=textField(x?.meaning,1600);return x&&refs&&theme!==null&&period!==null&&meaning!==null?{theme,period,meaning,evidence_refs:refs}:null;}):[];if(convergence.some(x=>x===null))return null;const summary=textField(r.summary,3200),precision=textField(r.precision_note,1800);if(summary===null||precision===null)return null;const conditions=Array.isArray(reb.conditions)&&reb.conditions.length<=4&&reb.conditions.every((x:unknown)=>typeof x==='string'&&x.length<=3600)?reb.conditions.slice():null;const patterns=Array.isArray(risk.patterns)&&risk.patterns.length<=4&&risk.patterns.every((x:unknown)=>typeof x==='string'&&x.length<=3600)?risk.patterns.slice():null;if(!conditions||!patterns)return null;return {summary,why_reconnect:why,initiative,timing:{conclusion:textField(t.conclusion,2600)??'',windows,evidence_refs:timingRefs},rebuild:{conclusion:textField(reb.conclusion,2600)??'',conditions,evidence_refs:rebuildRefs},repeat_risks:{conclusion:textField(risk.conclusion,2600)??'',patterns,evidence_refs:riskRefs},convergence,precision_note:precision};}\n'''
        pos=s.index(marker); s=s[:pos]+insert+s[pos:]
        old='out.reunion_reading=texts(r.reunion_reading,REUNION_LIMITS);\n  out.marriage_reading=texts(r.marriage_reading,MARRIAGE_LIMITS);'
        must(s,old,'public projection')
        s=s.replace(old,'out.reunion_reading=texts(r.reunion_reading,REUNION_LIMITS);\n  out.reunion_synthesis_v2=r.reunion_synthesis_v2===undefined?undefined:publicReunionV2(r.reunion_synthesis_v2);\n  if(r.reunion_synthesis_v2!==undefined&&!out.reunion_synthesis_v2)return null;\n  out.marriage_reading=texts(r.marriage_reading,MARRIAGE_LIMITS);',1)
    save(p,s)

